response:
**Gates before launch.** First I save the script as `spe/evals/harness/r04-workflow.js` and make a local commit, because you asked for a commit after each step. Then I run three gates in order and launch only if all three pass. Gate 1 is the grader selftest. I feed `grade.py` the oracle, which is `answers.json` written back as trial outputs, and all 50 rows must pass both the category and priority checks. An empty output and a wrong output with shifted labels must both score 0 without crashing. The selftest also confirms that `answers.json` has the same 50 ids as `args.tickets`. The eval set had 40 tickets before this round, so if the file still has 40, I halt and ask you, because the approved plan says 50. Gate 2 is the control. I regrade the round 3 outputs with this round's `grade.py` and compare them to the round 3 measured numbers in `spe/prediction-log.md`. Any difference comes from a grader change. I log it in `spe/failures.md` with both numbers side by side, and I halt if I cannot explain it. Gate 3 is a dry run with `only: ['B:T001', 'C2:T001', 'C2:T017']`, `trialsPerCell: 1`, `topupPerCell: 0` and `capUsd: 2`. It must return schema-valid output, real output and transcript files, a clean peek scan, matching grader row counts, and a tone score for every reply. I set `estTrialUsd` and `estJudgeUsd` from the dry run's measured cost. The full run is 500 trials plus 50 judge batches. That cost is an estimate until the run measures it. Defaults I chose: the runner flags match round 3, and `grade.py` takes `--answers` and `--input` and prints one JSON row per input line. The selftest and the dry run check both.

```js
export const meta = {
  name: 'spe-triage-eval',
  description: 'SPE eval round for the triage agent. Runs each config on each ticket, voids trials that peeked, grades labels with grade.py, judges reply tone blind with Opus, tops up split cells, and ends with failure analysis and a completeness critic.',
  phases: ['Setup', 'Trials', 'Integrity', 'Grade and judge', 'Top-up', 'Synthesis'],
};

// Arguments
// round              4
// configs            ['B', 'C2']
// tickets            the 50 ticket ids from spe/evals/tasks/answers.json, in file order
// expectedTickets    50
// trialsPerCell      5
// runner             the triage runner command used by r03-workflow.js
// runDir             absolute directory outside the repo for outputs and transcripts
// capUsd             40
// estTrialUsd        estimated runner spend per trial, set from the dry run
// estJudgeUsd        estimated Opus judge spend per ticket batch, set from the dry run
// estOverheadUsd     reserve for scan, grade, and synthesis agents
// topupPerCell       extra trials for a split cell (default 2)
// topupMaxCells      most cells that get a top-up (default 10)
// only               optional cell keys for the dry run, such as ['B:T001', 'C2:T017']
// agentTranscriptDir optional directory of this run's subagent transcripts

// ---------- Round and constants ----------
const ROUND = Number(args.round);
if (!Number.isInteger(ROUND) || ROUND < 1) throw new Error('args.round must be a positive integer');
const RTAG = 'r' + String(ROUND).padStart(2, '0');
const NEXT = ROUND + 1;

const CONFIGS = args.configs;
const TICKETS = args.tickets;
const TRIALS = args.trialsPerCell ?? 5;
const CAP = args.capUsd;
const OUT = `${args.runDir}/${RTAG}`;
const ONLY = Array.isArray(args.only) && args.only.length ? new Set(args.only) : null;
const TOPUP_PER_CELL = ONLY ? 0 : (args.topupPerCell ?? 2);
const TOPUP_MAX_CELLS = args.topupMaxCells ?? 10;
const MARK = `${RTAG}-trial-runner`;

// The runner legitimately loads ticket inputs from spe/evals/tasks/, so the scan
// looks for the answer key, graders, predictions, and plans only.
const FORBIDDEN = 'answers\\.json|spe/evals/graders/|grade\\.py|judge\\.md|spe/predictions/|spe/plans/|prediction-log\\.md';

// ---------- Helpers ----------
const range = (start, n) => Array.from({ length: n }, (_, i) => start + i);
const r3 = (x) => (x == null || Number.isNaN(x) ? null : Math.round(x * 1000) / 1000);
const mean = (xs) => { const v = xs.filter((x) => typeof x === 'number'); return v.length ? r3(v.reduce((a, b) => a + b, 0) / v.length) : null; };
const median = (xs) => { const v = xs.filter((x) => typeof x === 'number').sort((a, b) => a - b); if (!v.length) return null; const m = Math.floor(v.length / 2); return v.length % 2 ? v[m] : (v[m - 1] + v[m]) / 2; };
const rate = (arr, f) => (arr.length ? r3(arr.filter(f).length / arr.length) : null);
const rid = (key, trial) => `${key}#${trial}`;

function seededShuffle(list, seedText) {
  let h = 2166136261;
  for (const ch of seedText) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619); }
  let s = h >>> 0;
  const rnd = () => { s = (s + 0x6D2B79F5) >>> 0; let t = s; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
  const a = list.slice();
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
  return a;
}

// ---------- Budget ----------
let committed = 0; // reserved plus measured USD
const skips = [];
function reserve(usd, what) {
  if (committed + usd > CAP) {
    skips.push({ what, usd: r3(usd), committedAtSkip: r3(committed) });
    log(`SKIP ${what}: would cross the $${CAP} cap (committed $${r3(committed)}, needs $${r3(usd)})`);
    return false;
  }
  committed += usd;
  return true;
}
function settle(reserved, actual) {
  if (typeof actual === 'number' && actual >= 0) committed += actual - reserved;
}

// ---------- Schemas ----------
const TRIAL_SCHEMA = {
  type: 'object',
  required: ['trials'],
  properties: {
    trials: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial', 'status', 'output_path', 'transcript_path', 'cost_usd'],
        properties: {
          trial: { type: 'integer' },
          status: { type: 'string', enum: ['completed', 'harness_error', 'rate_limited'] },
          output_path: { type: 'string' },
          transcript_path: { type: 'string' },
          cost_usd: { type: 'number' },
          error: { type: 'string' },
        },
      },
    },
  },
};

const SCAN_SCHEMA = {
  type: 'object',
  required: ['triage_hits', 'runner_hits', 'files_scanned'],
  properties: {
    triage_hits: { type: 'array', items: { type: 'string' } },
    runner_hits: { type: 'array', items: { type: 'string' } },
    files_scanned: { type: 'integer' },
  },
};

const GRADE_SCHEMA = {
  type: 'object',
  required: ['grader_ok', 'rows_in', 'rows_out', 'ticket_text', 'rows'],
  properties: {
    grader_ok: { type: 'boolean' },
    grader_error: { type: 'string' },
    rows_in: { type: 'integer' },
    rows_out: { type: 'integer' },
    ticket_text: { type: 'string' },
    rows: {
      type: 'array',
      items: {
        type: 'object',
        required: ['key', 'trial', 'category_ok', 'priority_ok', 'reply', 'runtime_ms', 'tool_calls', 'tool_errors', 'tokens_in', 'tokens_out'],
        properties: {
          key: { type: 'string' },
          trial: { type: 'integer' },
          category_ok: { type: 'boolean' },
          priority_ok: { type: 'boolean' },
          got_category: { type: 'string' },
          got_priority: { type: 'string' },
          expected_category: { type: 'string' },
          expected_priority: { type: 'string' },
          reply: { type: 'string' },
          runtime_ms: { type: 'number' },
          tool_calls: { type: 'integer' },
          tool_errors: { type: 'integer' },
          tokens_in: { type: 'integer' },
          tokens_out: { type: 'integer' },
        },
      },
    },
  },
};

const JUDGE_SCHEMA = {
  type: 'object',
  required: ['scores'],
  properties: {
    scores: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'tone_score', 'tone_pass', 'reason'],
        properties: {
          id: { type: 'string' },
          tone_score: { type: 'number' },
          tone_pass: { type: 'boolean' },
          reason: { type: 'string' },
        },
      },
    },
  },
};

const FAILURE_SCHEMA = {
  type: 'object',
  required: ['failure_types', 'grader_suspects', 'proposals'],
  properties: {
    failure_types: {
      type: 'array',
      items: {
        type: 'object',
        required: ['name', 'kind', 'what', 'how_to_spot', 'seen_in', 'fix'],
        properties: {
          name: { type: 'string' },
          kind: { type: 'string', enum: ['agent', 'grader', 'harness', 'task'] },
          what: { type: 'string' },
          how_to_spot: { type: 'string' },
          seen_in: { type: 'array', items: { type: 'string' } },
          fix: { type: 'string' },
        },
      },
    },
    grader_suspects: { type: 'array', items: { type: 'string' } },
    proposals: { type: 'array', items: { type: 'string' } },
  },
};

const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'gaps'],
  properties: {
    complete: { type: 'boolean' },
    gaps: {
      type: 'array',
      items: {
        type: 'object',
        required: ['what', 'severity', 'fix'],
        properties: { what: { type: 'string' }, severity: { type: 'string', enum: ['blocking', 'minor'] }, fix: { type: 'string' } },
      },
    },
  },
};

// ---------- Setup ----------
phase('Setup');
if (!Array.isArray(CONFIGS) || !CONFIGS.length) throw new Error('args.configs is required');
if (!Array.isArray(TICKETS) || !TICKETS.length) throw new Error('args.tickets is required');
if (!ONLY && TICKETS.length !== args.expectedTickets) {
  throw new Error(`HALT: expected ${args.expectedTickets} tickets, got ${TICKETS.length}. Ask the user before running.`);
}

const allCells = [];
for (const config of CONFIGS) for (const ticket of TICKETS) allCells.push({ config, ticket, key: `${config}:${ticket}` });
const cells = ONLY ? allCells.filter((c) => ONLY.has(c.key)) : allCells;
if (!cells.length) throw new Error('args.only matched no cells');
const activeTickets = [...new Set(cells.map((c) => c.ticket))];

if (!reserve(args.estOverheadUsd, 'overhead reserve')) throw new Error('HALT: the cap cannot cover the overhead reserve');
if (!reserve(args.estJudgeUsd * activeTickets.length, 'base judge reserve')) throw new Error('HALT: the cap cannot cover base judging');

log(`${RTAG}: ${CONFIGS.join(', ')} x ${activeTickets.length} tickets x ${TRIALS} trials = ${cells.length * TRIALS} trials. Cap $${CAP}.`);
if (ONLY) log(`DRY RUN on ${cells.map((c) => c.key).join(', ')}. Top-up is off.`);
log('The judge is Opus, which is the same model family as the Sonnet trials. No judge from another family is available here, so tone scores may share blind spots.');

// ---------- Trials ----------
const records = new Map(); // rid -> record

function trialPrompt(cell, start, n, topup) {
  const lines = [
    `[${MARK} ${cell.key} ${topup ? 'topup' : 'base'}]`,
    'You run one cell of a fixed eval. You are a runner. You do not solve the ticket.',
    'Do not read, open, list, or search any file in the repository. Do not look inside the spe/ folder.',
    `Run the command below once for each trial number from ${start} to ${start + n - 1}. Replace <N> with the trial number.`,
    '',
    `${args.runner} --config ${cell.config} --ticket ${cell.ticket} --trial <N> --out ${OUT}/${cell.config}/${cell.ticket}/t<N>.json --transcript ${OUT}/${cell.config}/${cell.ticket}/t<N>.transcript.jsonl`,
    '',
    'After each run, check that both files exist with `test -f`. Do not open them.',
    'Set status to "completed" when the command exits 0 and both files exist.',
    'Set status to "rate_limited" when the runner reports a rate limit. Otherwise set status to "harness_error" and copy the last error line into error.',
    'Set cost_usd to the number on the runner\'s last line in the form "cost_usd=<number>". Use -1 if that line is missing.',
    'Report every trial number, including failed ones.',
  ];
  return lines.join('\n');
}

async function runCell(cell, start, n, topup) {
  const est = args.estTrialUsd * n + (topup ? args.estJudgeUsd : 0);
  if (!reserve(est, `${cell.key} trials ${start}-${start + n - 1}${topup ? ' (top-up)' : ''}`)) return [];
  const wanted = range(start, n);
  let reported = [];
  try {
    const res = await agent(trialPrompt(cell, start, n, topup), {
      label: `trial ${cell.key}${topup ? ' top-up' : ''}`,
      phase: topup ? 'Top-up' : 'Trials',
      schema: TRIAL_SCHEMA,
    });
    reported = res.trials.filter((t) => wanted.includes(t.trial));
    const runnerCost = reported.reduce((s, t) => s + (t.cost_usd >= 0 ? t.cost_usd : args.estTrialUsd), 0);
    settle(est, runnerCost + (topup ? args.estJudgeUsd : 0));
  } catch (e) {
    log(`HARNESS ERROR ${cell.key}: ${String(e).slice(0, 200)}`);
  }
  const out = wanted.map((t) => {
    const r = reported.find((x) => x.trial === t);
    const rec = r
      ? { ...cell, ...r, topup, voided: false }
      : { ...cell, trial: t, status: 'harness_error', error: 'not reported by runner agent', topup, voided: false };
    records.set(rid(cell.key, t), rec);
    return rec;
  });
  return out;
}

phase('Trials');
await pipeline(cells, (cell) => runCell(cell, 1, TRIALS, false));

// ---------- Integrity ----------
async function scanForPeeks(subset) {
  const agentDir = args.agentTranscriptDir;
  const prompt = [
    'You check trial transcripts for reads of the answer key, graders, predictions, or plans. Use grep only. Do not open the matched files.',
    `1. Run: grep -rlE '${FORBIDDEN}' ${OUT} --include='*.transcript.jsonl'`,
    '   Put every path it prints in triage_hits.',
    agentDir
      ? `2. Run: grep -rl '${MARK}' ${agentDir} | xargs grep -lE '${FORBIDDEN}'\n   For each file it prints, run: grep -oE '\\[${MARK} [^]]+\\]' <file>\n   Put each match in runner_hits, without the brackets and without the leading "${MARK} " text.`
      : '2. No runner transcript directory was given. Return runner_hits as an empty list.',
    `3. Set files_scanned to the number printed by: find ${OUT} -name '*.transcript.jsonl' | wc -l`,
  ].join('\n');
  const scan = await agent(prompt, { label: 'peek scan', phase: 'Integrity', schema: SCAN_SCHEMA });
  if (!agentDir) log('Runner transcripts were not scanned because args.agentTranscriptDir is unset. Only triage transcripts were checked.');

  const subsetIds = new Set(subset.map((r) => rid(r.key, r.trial)));
  const triageHits = subset.filter((r) => r.transcript_path && scan.triage_hits.includes(r.transcript_path));
  if (triageHits.length) {
    throw new Error(`HALT: the triage agent reached the answer key or graders in ${triageHits.length} trial(s), e.g. ${triageHits.slice(0, 3).map((r) => rid(r.key, r.trial)).join(', ')}. Report to the user.`);
  }
  let voided = 0;
  for (const hit of scan.runner_hits) {
    const m = hit.trim().match(/^(\S+:\S+) (base|topup)$/);
    if (!m) continue;
    for (const rec of subset) {
      if (rec.key === m[1] && (m[2] === 'topup') === rec.topup && subsetIds.has(rid(rec.key, rec.trial)) && !rec.voided) {
        rec.voided = true;
        voided++;
        log(`VOID ${rid(rec.key, rec.trial)}: the runner agent touched a forbidden path`);
      }
    }
  }
  log(`Peek scan: ${scan.files_scanned} transcripts, ${voided} trial(s) voided.`);
  return voided;
}

phase('Integrity');
const baseRecords = [...records.values()];
await scanForPeeks(baseRecords);

// ---------- Grade and judge ----------
const graded = new Map(); // rid -> graded row

async function gradeTicket(ticket, recs, suffix) {
  const lines = recs.map((r) => JSON.stringify({ key: r.key, trial: r.trial, output_path: r.output_path }));
  const prompt = [
    'You run the fixed code grader. Do not edit the grader, the answers, or any output file.',
    `1. Write these lines, one per line, to ${OUT}/grade-in/${ticket}${suffix}.jsonl:`,
    lines.join('\n'),
    `2. Run: python3 spe/evals/graders/grade.py --answers spe/evals/tasks/answers.json --input ${OUT}/grade-in/${ticket}${suffix}.jsonl`,
    '3. Return each row the grader prints, unchanged. Match each row to its key and trial by output_path.',
    '4. For each row, copy these fields from its output file with jq: reply, runtime_ms, tool_calls, tool_errors, tokens_in, tokens_out. Copy reply exactly.',
    '5. Copy ticket_text from the ticket.body field of the first output file.',
    `6. Set rows_in to ${lines.length}. Set rows_out to the number of rows the grader printed.`,
    'Set grader_ok to false if the grader exits non-zero, prints a different number of rows, or prints a row you cannot match. Put the reason in grader_error.',
  ].join('\n');
  const g = await agent(prompt, { label: `grade ${ticket}${suffix}`, phase: suffix ? 'Top-up' : 'Grade and judge', schema: GRADE_SCHEMA });
  if (!g.grader_ok || g.rows_out !== lines.length || g.rows.length !== lines.length) {
    throw new Error(`HALT: broken grader on ${ticket}${suffix}: ${g.grader_error || `rows_in ${lines.length}, rows_out ${g.rows_out}`}`);
  }
  const rows = g.rows.map((row) => {
    const rec = records.get(rid(row.key, row.trial));
    const full = { ...row, config: rec.config, ticket, topup: rec.topup, tone_score: null, tone_pass: null, tone_reason: null };
    graded.set(rid(row.key, row.trial), full);
    return full;
  });
  return { ticket, suffix, ticket_text: g.ticket_text, rows };
}

async function judgeTicket(g) {
  if (!g.rows.length) return g;
  const blind = seededShuffle(g.rows, `${RTAG}:${g.ticket}${g.suffix}`).map((row, i) => ({ id: `R${i + 1}`, row }));
  const prompt = [
    'You are the reply tone judge. Read spe/evals/graders/judge.md and apply it exactly.',
    'Score only tone, as judge.md defines it. Do not score the category or the priority.',
    'You do not know which setup wrote each reply. Do not try to guess.',
    'Do not read anything under spe/predictions/ or spe/plans/.',
    '',
    'Ticket:',
    '<<<',
    g.ticket_text,
    '>>>',
    '',
    ...blind.flatMap((b) => [`### ${b.id}`, '<<<', b.row.reply, '>>>', '']),
    `Return one score for each of ${blind.map((b) => b.id).join(', ')}.`,
  ].join('\n');
  try {
    const j = await agent(prompt, { label: `judge ${g.ticket}${g.suffix}`, phase: g.suffix ? 'Top-up' : 'Grade and judge', schema: JUDGE_SCHEMA, model: 'opus' });
    for (const b of blind) {
      const s = j.scores.find((x) => x.id === b.id);
      if (!s) { log(`JUDGE MISSING ${g.ticket} ${b.id}`); continue; }
      b.row.tone_score = s.tone_score;
      b.row.tone_pass = s.tone_pass;
      b.row.tone_reason = s.reason;
    }
  } catch (e) {
    log(`JUDGE ERROR ${g.ticket}${g.suffix}: ${String(e).slice(0, 200)}`);
  }
  return g;
}

function gradableByTicket(recs) {
  const by = new Map();
  for (const r of recs) {
    if (r.status !== 'completed' || r.voided) continue;
    if (!by.has(r.ticket)) by.set(r.ticket, []);
    by.get(r.ticket).push(r);
  }
  return [...by.entries()];
}

phase('Grade and judge');
await pipeline(
  gradableByTicket(baseRecords),
  ([ticket, recs]) => gradeTicket(ticket, recs, ''),
  (g) => judgeTicket(g),
);

// ---------- Top-up ----------
phase('Top-up');
const passOf = (row) => row.category_ok && row.priority_ok;
const splitCells = cells
  .map((cell) => {
    const rows = range(1, TRIALS).map((t) => graded.get(rid(cell.key, t))).filter(Boolean);
    const passRate = rows.length ? rows.filter(passOf).length / rows.length : null;
    return { cell, rows: rows.length, passRate };
  })
  .filter((x) => x.passRate !== null && x.passRate > 0 && x.passRate < 1)
  .sort((a, b) => Math.abs(a.passRate - 0.5) - Math.abs(b.passRate - 0.5));

const topupTargets = TOPUP_PER_CELL > 0 ? splitCells.slice(0, TOPUP_MAX_CELLS) : [];
log(`${splitCells.length} split cell(s). Topping up ${topupTargets.length} with ${TOPUP_PER_CELL} trial(s) each.`);
if (splitCells.length > topupTargets.length && TOPUP_PER_CELL > 0) {
  log(`Not topped up (cell cap): ${splitCells.slice(TOPUP_MAX_CELLS).map((x) => x.cell.key).join(', ')}`);
}

let topupRecords = [];
if (topupTargets.length) {
  const results = await pipeline(topupTargets, (x) => runCell(x.cell, TRIALS + 1, TOPUP_PER_CELL, true));
  topupRecords = results.flat().filter(Boolean);
  if (topupRecords.length) {
    await scanForPeeks(topupRecords);
    await pipeline(
      gradableByTicket(topupRecords),
      ([ticket, recs]) => gradeTicket(ticket, recs, '-topup'),
      (g) => judgeTicket(g),
    );
  }
}

// ---------- Synthesis ----------
phase('Synthesis');

function summarize(rows) {
  const out = {};
  for (const config of CONFIGS) {
    const r = rows.filter((x) => x.config === config);
    const toned = r.filter((x) => typeof x.tone_pass === 'boolean');
    out[config] = {
      graded_trials: r.length,
      category_acc: rate(r, (x) => x.category_ok),
      priority_acc: rate(r, (x) => x.priority_ok),
      both_acc: rate(r, passOf),
      tone_judged: toned.length,
      tone_pass_rate: rate(toned, (x) => x.tone_pass),
      tone_mean: mean(toned.map((x) => x.tone_score)),
      runtime_ms_median: median(r.map((x) => x.runtime_ms)),
      tool_calls_mean: mean(r.map((x) => x.tool_calls)),
      tokens_mean: mean(r.map((x) => x.tokens_in + x.tokens_out)),
      tool_errors_mean: mean(r.map((x) => x.tool_errors)),
      tool_error_trial_rate: rate(r, (x) => x.tool_errors > 0),
    };
  }
  return out;
}

function counts() {
  const out = {};
  for (const config of CONFIGS) {
    const recs = [...records.values()].filter((r) => r.config === config);
    out[config] = {
      launched: recs.length,
      completed: recs.filter((r) => r.status === 'completed' && !r.voided).length,
      harness_error: recs.filter((r) => r.status === 'harness_error').length,
      rate_limited: recs.filter((r) => r.status === 'rate_limited').length,
      voided: recs.filter((r) => r.voided).length,
    };
  }
  return out;
}

const allGraded = [...graded.values()];
const base = summarize(allGraded.filter((x) => !x.topup)); // scores the saved prediction
const withTopup = summarize(allGraded);
const trialCounts = counts();
const voidedList = [...records.values()].filter((r) => r.voided).map((r) => rid(r.key, r.trial));
const harnessErrors = [...records.values()].filter((r) => r.status !== 'completed').map((r) => ({ id: rid(r.key, r.trial), status: r.status, error: r.error || '' }));
const untoned = allGraded.filter((x) => typeof x.tone_pass !== 'boolean').map((x) => rid(x.key, x.trial));

const failures = allGraded
  .filter((x) => !passOf(x) || x.tone_pass === false)
  .map((x) => ({
    id: rid(x.key, x.trial),
    got: `${x.got_category ?? '?'} / ${x.got_priority ?? '?'}`,
    expected: `${x.expected_category ?? '?'} / ${x.expected_priority ?? '?'}`,
    category_ok: x.category_ok,
    priority_ok: x.priority_ok,
    tone_pass: x.tone_pass,
    tone_reason: x.tone_reason,
    tool_errors: x.tool_errors,
  }));

let failureAnalysis = null;
try {
  failureAnalysis = await agent(
    [
      `You analyse failures from eval round ${RTAG} of the triage agent. Configs: ${CONFIGS.join(', ')}.`,
      `You may read run outputs and transcripts under ${OUT}, and the grader code. Do not read spe/predictions/ or spe/plans/.`,
      'Group the failures below into failure types. Give each one a name, a kind (agent, grader, harness, or task), What, How to spot it, Seen in (trial ids), and Fix.',
      'If a reference label looks wrong or the grader misreads a valid answer, list that trial id in grader_suspects and record a grader failure type.',
      `List concrete changes to propose for round ${NEXT} in proposals. Change one thing per config.`,
      '',
      'Per config, base trials:',
      JSON.stringify(base, null, 2),
      'Failures:',
      JSON.stringify(failures, null, 2),
      'Harness errors (not model failures):',
      JSON.stringify(harnessErrors, null, 2),
    ].join('\n'),
    { label: 'failure analysis', phase: 'Synthesis', schema: FAILURE_SCHEMA, model: 'opus' },
  );
} catch (e) {
  log(`FAILURE ANALYSIS ERROR: ${String(e).slice(0, 200)}`);
}

let critic = null;
try {
  critic = await agent(
    [
      `You are the completeness critic for eval round ${RTAG}. Do not read spe/predictions/ or spe/plans/.`,
      `The approved plan: configs ${CONFIGS.join(' and ')}, ${args.expectedTickets} tickets, ${TRIALS} trials per cell, code grader for category and priority, Opus judge for reply tone, spend cap $${CAP}.`,
      ONLY ? `This was a dry run on ${[...ONLY].join(', ')}. Judge it as a dry run.` : 'This was the full run.',
      'Check each item against the facts below. Report any cell short of its trials, skipped spend, voided trials, harness errors, ungraded or unjudged trials, and anything else the plan required that is missing.',
      'Mark a gap blocking if it would change a measured number enough to change a verdict.',
      '',
      JSON.stringify({ trialCounts, skips, voidedList, harnessErrors, untoned, splitCells: splitCells.length, toppedUp: topupTargets.map((x) => x.cell.key), committedUsd: r3(committed), capUsd: CAP }, null, 2),
    ].join('\n'),
    { label: 'completeness critic', phase: 'Synthesis', schema: CRITIC_SCHEMA, model: 'opus' },
  );
} catch (e) {
  log(`CRITIC ERROR: ${String(e).slice(0, 200)}`);
}

log(`Done. Committed spend $${r3(committed)} of $${CAP}. ${skips.length} skip(s). ${voidedList.length} void(s).`);

return {
  round: ROUND,
  dryRun: Boolean(ONLY),
  configs: CONFIGS,
  trialsPerCell: TRIALS,
  base,
  withTopup,
  trialCounts,
  skips,
  voided: voidedList,
  harnessErrors,
  untoned,
  splitCells: splitCells.map((x) => ({ key: x.cell.key, passRate: r3(x.passRate) })),
  toppedUp: topupTargets.map((x) => x.cell.key),
  spend: { committedUsd: r3(committed), capUsd: CAP },
  judgeNote: 'Opus judge, same family as the trial model. No other-family judge was available.',
  failureAnalysis,
  critic,
};
